sp_header_footer.client_script:
api.controller = function () {
    /* widget controller */
    var c = this;
};

sp_header_footer.css:
.sss-navbar {
  background: $brand-primary;
  border-bottom: 4px solid $brand-warning;
  color: $btn-primary-color;
  min-height: 76px;
}

.sss-skip-link {
  background: $brand-warning;
  color: #000000;
  font-weight: 700;
  left: 12px;
  padding: 10px 16px;
  position: absolute;
  top: -100px;
  z-index: 10000;
}

.sss-skip-link:focus { top: 10px; }

.sss-navbar__inner,
.sss-navbar__brand {
  align-items: center;
  display: flex;
}

.sss-navbar__inner {
  justify-content: space-between;
  min-height: 76px;
}

.sss-navbar__brand,
.sss-navbar__brand:hover,
.sss-navbar__brand:focus {
  color: $btn-primary-color;
  text-decoration: none;
}

.sss-navbar__brand:focus {
  outline: 3px solid $brand-warning;
  outline-offset: 4px;
}

.sss-navbar__logo {
  display: block;
  height: 36px;
  width: 139px;
}

.sss-navbar__divider {
  background: $btn-primary-color;
  height: 42px;
  margin: 0 18px;
  opacity: .8;
  width: 2px;
}

.sss-navbar__product {
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -.01em;
}

.sss-navbar__links {
  align-items: center;
  display: flex;
  gap: 8px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.sss-navbar__links a {
  border-radius: 999px;
  color: $btn-primary-color;
  display: block;
  font-weight: 700;
  padding: 10px 14px;
}

.sss-navbar__links a:hover {
  background: #002faf;
  color: $btn-primary-color;
  text-decoration: none;
}

.sss-navbar__links a:focus {
  outline: 3px solid $brand-warning;
  outline-offset: 2px;
}

@media (max-width: 767px) {
  .sss-navbar__links { display: none; }
  .sss-navbar__product { font-size: 13px; }
  .sss-navbar__divider { height: 32px; margin: 0 10px; }
  .sss-navbar__logo { height: 28px; width: 108px; }
}
